import json, math
from pathlib import Path
S='9702-7.5'; K1=S+'.1'; K2=S+'.2'
P=Path('build/out/packs/9702/9702-7.5.json')
angle=lambda d: math.cos(math.radians(d))**2
v1=8*angle(50); v2=v1*angle(30)
assert round(v2,1)==2.5 and round(angle(30)*angle(60),2)==0.19
mis=[
 dict(id='m1',kc=K1,statement='Longitudinal waves can be polarised.',refutation='Polarisation selects a direction of vibration perpendicular to propagation; longitudinal vibrations have no such transverse direction.',contrast='Light can be polarised; ordinary sound in air cannot.',source='ER 9702 w22 P21 Q4'),
 dict(id='m2',kc=K2,statement='Use each filter angle relative to the original polarisation.',refutation='The transmitted wave is polarised along the preceding filter axis, so the next angle is between adjacent axes.',contrast='For axes at 50° and 20° to vertical, the second angle is 30°.',source='ER 9702 s22 P12 Q26'),
 dict(id='m3',kc=K2,statement='Amplitude falls by cos²θ.',refutation='Intensity is proportional to amplitude squared; amplitude falls by the magnitude of cos θ.',contrast='At 50°, intensity ratio is 0.413 but amplitude ratio is 0.643.',source='ER 9702 s23 P11 Q24'),
 dict(id='m4',kc=K2,statement='A second filter cannot restore transmission after crossed filters.',refutation='An intermediate filter at 45° transmits light and resets its plane of polarisation, allowing the last filter to transmit some.',contrast='Crossed pair alone transmits zero; with the middle filter, transmission is nonzero.',source='ER 9702 s23 P12 Q24')]
items=[]
def short(n,k,stem,points,ex,diff=2):
 items.append(dict(id=f'{S}-i{n:02d}',kcs=[k],kind='short',difficulty=diff,command_word=stem.split()[0],source={'type':'generated'},stem=stem,marks=len(points),rubric=[{'point':p,'keywords':keys} for p,keys in points],explanation=ex,hints=['Recall the wave direction involved.','Compare vibration with propagation.','Name the relevant plane or axis.']))
short(1,K1,'Describe polarisation of a transverse wave.',[('Vibrations are restricted to one plane perpendicular to the direction of propagation.',[['one','single'],['plane'],['perpendicular','transverse']])],'Polarisation restricts transverse vibration to one plane.')
short(2,K1,'Explain why ordinary sound in air cannot be polarised.',[('Sound in air is longitudinal.',[['longitudinal']]),('Its vibrations are parallel to propagation, so there are no alternative transverse planes to select.',[['parallel'],['direction','propagation']])],'Sound in air is longitudinal and cannot have its vibration plane selected.')
short(3,K1,'Identify the wave property demonstrated when a rotating filter changes the intensity of transmitted light.',[('Polarisation.',[['polarisation','polarization']])],'A polarising filter selects a vibration plane.')
short(4,K1,'Compare the ability of light and sound in air to be polarised.',[('Light is transverse and can be polarised.',[['light'],['transverse'],['polarised','polarized']]),('Sound in air is longitudinal and cannot be polarised.',[['sound'],['longitudinal'],['cannot','not']])],'Only the transverse light wave can be polarised.',4)
short(5,K1,'State what the plane of vibration means for plane-polarised light.',[('The electric-field vibrations are confined to one plane containing the direction of propagation.',[['electric','field'],['one','single'],['plane']])],'Plane-polarised electromagnetic radiation has one electric-field vibration plane.')
short(6,K1,'Explain how polarisation provides evidence that electromagnetic waves are transverse.',[('Polarisation restricts vibrations to a plane perpendicular to propagation.',[['perpendicular','transverse'],['plane']]),('Only transverse waves can be polarised.',[['transverse'],['polarised','polarized']])],'The ability to select a transverse vibration plane establishes transverse behaviour.',4)
# Numeric generator uses formulas for all values and distractors.
def num(n,stem,angles,start=8.0,diff=3):
 ans=start
 for a in angles: ans*=angle(a)
 wrong1=start*angle(angles[-1]); wrong2=start
 items.append(dict(id=f'{S}-i{n:02d}',kcs=[K2],kind='numeric',difficulty=diff,command_word='Calculate',source={'type':'generated'},stem=stem,marks=2,answer={'value':round(ans,6),'unit':'W m^-2','sf_ok':[2,3]},distractors=[{'value':round(wrong2,6),'misconception':'m3'}] if len(angles)==1 else [{'value':round(wrong1,6),'misconception':'m2'},{'value':round(wrong2,6),'misconception':'m3'}],explanation='Apply $I=I_0\\cos^2\\theta$ to each filter, using the angle between the incident polarisation and that filter axis.',hints=['Track the polarisation direction after each filter.','Use Malus’s law successively.','First calculate the intensity after the first filter.']))
num(7,'Calculate the intensity after a filter at 60° to vertically polarised light of intensity 8.0 W m^-2.',[60])
num(8,'Calculate the final intensity for vertically polarised light of intensity 8.0 W m^-2 passing filters at 50° and then 20° to vertical.',[50,30],diff=4)
num(9,'Calculate the final intensity for vertically polarised light of intensity 12 W m^-2 passing filters at 30° and then 90° to vertical.',[30,60],12,diff=4)
short(10,K2,'State Malus’s law for a plane-polarised electromagnetic wave.',[('$I=I_0\\cos^2\\theta$, where θ is the angle between incident polarisation and transmission axis.',[['cos'],['intensity','I_0'],['angle','theta']])],'Malus’s law gives transmitted intensity from incident plane-polarised intensity.')
short(11,K2,'Explain why the intensity is zero when the transmission axis is perpendicular to the incident plane of polarisation.',[('The angle is 90° and cos²90° = 0.',[['90'],['cos'],['zero','0']])],'Malus’s law gives zero transmission for crossed directions.')
short(12,K2,'Describe how to calculate intensity through a series of polarising filters.',[('Apply Malus’s law to each filter successively.',[['Malus'],['each','successive']]),('Use the angle between consecutive axes after the first filter.',[['angle'],['axes','axis'],['consecutive','adjacent']])],'Each output becomes the next input, polarised along the latest filter axis.',4)
bank={x['id']:x for x in json.loads(Path('build/work/mcq/9702.tagged.json').read_text())}
ids=['9702_s22_12_q26','9702_w22_12_q23','9702_s23_11_q24','9702_s23_12_q24','9702_w23_12_q24','9702_w23_13_q24','9702_s24_11_q24','9702_s24_11_q29','9702_s24_12_q24','9702_w24_11_q29','9702_s25_11_q28','9702_s25_13_q25']
expl={
'9702_s22_12_q26':'The angles are 50° then 30°, giving $8.0\\cos^250°\\cos^230°=2.5\\\,\\mathrm{W\\,m^{-2}}$. Option C uses 20° for the second filter, ignoring the new polarisation direction.',
'9702_s23_11_q24':'The angle to vertical is 50°. Intensity ratio is $\\cos^250°$, while amplitude ratio is $\\cos50°=0.64$; B and D confuse the angle or intensity with amplitude.',
'9702_s23_12_q24':'Each of the two filters makes 45° to the incoming polarisation, giving $I_0\\cos^245°\\cos^245°=I_0/4$. Option C applies the law only once.',
'9702_w23_12_q24':'The middle filter makes 45° to each crossed direction, giving $I_0\\cos^245°\\cos^245°=I_0/4$. Option A assumes crossed end filters still block all light.',
'9702_w23_13_q24':'The angles are 30° then 60°, giving $I_0\\cos^230°\\cos^260°\approx0.19I_0$. Option D uses the final axis relative to the initial polarisation.',
'9702_s24_11_q24':'Since intensity is proportional to amplitude squared, $A_{out}=A\\cos\\theta$. Option B applies the intensity factor directly to amplitude.',
}
for i,qid in enumerate(ids,1):
 m=bank[qid]; kcs=[k for k in m['kcs'] if k in (K1,K2)]
 e=expl.get(qid, 'Polarisation is possible for transverse waves because their vibrations can be restricted to one transverse plane. The tempting alternative confuses this with a property shared by longitudinal waves.' if K1 in kcs else 'Use Malus’s law with the angle to the incident polarisation; the common wrong choice uses an angle to the original direction or confuses intensity with amplitude.')
 items.append(dict(id=f'{S}-p{i:02d}',kcs=kcs,kind='mcq',difficulty=3,command_word=None,source={'type':'past','ref':m['ref'],'qid':qid},stem=m['stem'],options=m['options'],answer=m['answer'],**({'image':m['image']} if m.get('image') else {}),marks=1,explanation=e,hints=[],distractors={}))
pack={'subtopic':S,'spec':'9702','version':1,'note':'Subjects/9702 Physics/07 Waves/7.5 Polarisation.md','outline':'Polarisation confines transverse vibration to one plane. Electromagnetic waves can be polarised; longitudinal sound waves in air cannot. For incident plane-polarised radiation, $I=I_0\\cos^2\\theta$. After each filter the transmitted radiation is polarised along its transmission axis, so successive angles are between adjacent axes. Intensity is proportional to amplitude squared.','misconceptions':mis,'worked':[{'id':'we1','kc':K2,'problem':'Vertically polarised light of intensity 8.0 W m^-2 passes filters with axes 50° then 20° to vertical. Calculate final intensity.','steps':[{'do':'$I_1=I_0\\cos^250°$.','why':'Use the angle between the incident vertical polarisation and the first axis.'},{'do':f'$I_1=8.0\\cos^250°={v1:.3f}\\\,\\mathrm{{W\\,m^{{-2}}}}$.','why':'The first output becomes the incident intensity at the second filter.'},{'do':f'$I_2=I_1\\cos^230°={v2:.2f}\\\,\\mathrm{{W\\,m^{{-2}}}}$.','why':'The second axis is 30° from the first, not 20° from the original vertical.','check':{'kind':'numeric','answer':{'value':round(v2,2),'unit':'W m^-2','sf_ok':[2,3]}}}], 'faded':{'id':'we1f','problem':'Vertically polarised light of intensity 12 W m^-2 passes axes 30° then 90° to vertical. Find final intensity.','answer':{'value':round(12*angle(30)*angle(60),3),'unit':'W m^-2','sf_ok':[2,3]},'blank_from':1}}], 'items':items,'flashcards':[{'id':'fc1','kc':K1,'front':'What is polarisation?','back':'The restriction of transverse wave vibrations to one plane perpendicular to the direction of propagation.'},{'id':'fc2','kc':K2,'front':'State Malus’s law and define θ.','back':'$I=I_0\\cos^2\\theta$; θ is the angle between the incident plane of polarisation and the filter transmission axis.'}], 'diagrams':[]}
P.write_text(json.dumps(pack,ensure_ascii=False,indent=1))
